// Auto-refresh token if expired OR missing required role before sending Initiate Upload
function parseJwt(token) {
    if (!token) return null;
    try {
        var parts = token.split('.');
        if (parts.length < 2) return null;
        if (typeof Buffer !== 'undefined') {
            return JSON.parse(Buffer.from(parts[1], 'base64').toString('utf8'));
        } else if (typeof atob !== 'undefined') {
            return JSON.parse(atob(parts[1].replace(/-/g, '+').replace(/_/g, '/')));
        }
    } catch (e) {}
    return null;
}

function isTokenValidForRole(token, requiredRole) {
    var payload = parseJwt(token);
    if (!payload || !payload.exp) return false;
    var now = Math.floor(Date.now() / 1000);
    if (payload.exp < (now + 30)) return false;
    if (requiredRole) {
        var roles = (payload.realm_access && payload.realm_access.roles) || [];
        if (!roles.includes(requiredRole)) return false;
    }
    return true;
}

