const baseUrl = pm.environment.get("baseUrl") || pm.variables.get("baseUrl");
const databankId = pm.environment.get("providerDatabankId") || pm.variables.get("providerDatabankId");
const token = pm.environment.get("providerToken") || pm.variables.get("providerToken");
const uploadKey = "postman-upload.csv";

// 1. Initiate upload
pm.sendRequest({
    url: `${baseUrl}/v1/databanks/${databankId}/uploads`,
    method: 'POST',
    header: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
    body: { mode: 'raw', raw: JSON.stringify({ key: uploadKey, contentType: 'text/csv', numParts: 1 }) }
}, function (err, res) {
    if (err || res.code >= 400) return console.error("Init failed:", res.text());
    const initData = res.json();
    const uploadId = initData.data.uploadId;
    const presignedUrl = initData.data.parts[0].presignedUrl;

    // 2. Upload part to S3
    pm.sendRequest({
        url: presignedUrl,
        method: 'PUT',
        header: { 'Content-Type': 'text/csv' },
        body: { mode: 'raw', raw: 'col1,col2\nval1,val2\n' }
    }, function (s3Err, s3Res) {
        if (s3Err || s3Res.code >= 400) return console.error("S3 failed:", s3Res.text());
        const etag = (s3Res.headers.get("ETag") || "").replace(/["']/g, '');

        // 3. Inject matching pair directly into current request
        pm.request.url.path[pm.request.url.path.length - 1] = uploadId;
        pm.request.body.raw = JSON.stringify({
            key: uploadKey,
            parts: [{ PartNumber: 1, ETag: etag }]
        });
    });
});

